PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS devices (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, last_sync_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS facebook_groups (id INTEGER PRIMARY KEY AUTOINCREMENT, device_id INTEGER NOT NULL, facebook_key TEXT NOT NULL, facebook_id TEXT, group_name TEXT NOT NULL, group_url TEXT NOT NULL, image_url TEXT, enabled INTEGER NOT NULL DEFAULT 1, last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(device_id, facebook_key), FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_group_name ON facebook_groups(group_name);
CREATE TABLE IF NOT EXISTS sync_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, device_id INTEGER NOT NULL, received_count INTEGER NOT NULL DEFAULT 0, ip_address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
